public enum BodyPartReferenceKind
{
    BodyPartID,
    BodyPartPath,
}

public sealed class BodyPartReference
{
    public BodyPartReferenceKind Kind { get; private set; }
    /// <summary>ASN.1 alias BodyPartID ::= INTEGER.</summary>
    public uint? BodyPartID { get; private set; }
    /// <summary>ASN.1 alias BodyPartPath ::= SEQUENCE OF BodyPartID.</summary>
    public uint[]? BodyPartPath { get; private set; }

    public static BodyPartReference FromBodyPartID(uint bodyPartID) => new BodyPartReference
    {
        Kind = BodyPartReferenceKind.BodyPartID,
        BodyPartID = bodyPartID,
    };

    public static BodyPartReference FromBodyPartPath(uint[] bodyPartPath) => new BodyPartReference
    {
        Kind = BodyPartReferenceKind.BodyPartPath,
        BodyPartPath = bodyPartPath,
    };

    public override string ToString()
    {
        return Kind switch
        {
            BodyPartReferenceKind.BodyPartID => Asn1Formatting.Format(BodyPartID),
            BodyPartReferenceKind.BodyPartPath => Asn1Formatting.Format(BodyPartPath),
            _ => "<unset>",
        };
    }

    public void Encode(Asn1Writer writer)
    {
        switch (Kind)
        {
            case BodyPartReferenceKind.BodyPartID:
                writer.WriteInteger(Asn1Tag.Integer, BodyPartID.Value);
                break;
            case BodyPartReferenceKind.BodyPartPath:
                writer.WriteSequenceOf(Asn1Tag.Sequence, BodyPartPath, static (inner, item) =>
                {
                    inner.WriteInteger(Asn1Tag.Integer, item);
                });
                break;
            default: throw new Asn1Exception("CHOICE has no alternative.");
        }
    }

    public static BodyPartReference Decode(Asn1Reader reader)
    {
        if (!reader.TryPeekTag(out var peeked)) throw new Asn1Exception("Empty CHOICE.");
        var value = new BodyPartReference();
        if (peeked.MatchesIgnoreConstructed(Asn1Tag.Integer))
        {
            value.Kind = BodyPartReferenceKind.BodyPartID;
            value.BodyPartID = reader.ReadUInt32(Asn1Tag.Integer);
        }
        else if (peeked.MatchesIgnoreConstructed(Asn1Tag.Sequence))
        {
            value.Kind = BodyPartReferenceKind.BodyPartPath;
            value.BodyPartPath = reader.ReadSequenceOf(Asn1Tag.Sequence, static inner => inner.ReadUInt32(Asn1Tag.Integer));
        }
        else throw new Asn1Exception("Unknown CHOICE alternative.");
        return value;
    }
}

