    public uint[] CertReferences { get; set; } = Array.Empty<uint>();
    public bool Replace { get; set; } = true;
    public Asn1Kit.Modern.PKIXCRMF2009.CertTemplate CertTemplate { get; set; }

    public void Encode(Asn1Writer writer) => Encode(writer, DefaultTag);

    public void Encode(Asn1Writer writer, Asn1Tag tag)
    {
        using (writer.EnterSequence(tag))
        {
            writer.WriteSequenceOf(Asn1Tag.Sequence, PkiDataReference, static (inner, item) =>
            {
                inner.WriteInteger(Asn1Tag.Integer, item);
            });
            writer.WriteSequenceOf(Asn1Tag.Sequence, CertReferences, static (inner, item) =>
            {
                inner.WriteInteger(Asn1Tag.Integer, item);
            });
            if (Replace != true)
            {
                writer.WriteBoolean(Asn1Tag.Boolean, Replace);
            }
            CertTemplate.Encode(writer, Asn1Tag.Sequence);
        }
    }

    public static ModCertTemplate Decode(Asn1Reader reader) => Decode(reader, DefaultTag);

    public static ModCertTemplate Decode(Asn1Reader reader, Asn1Tag tag)
    {
        using (reader.EnterSequence(tag))
        {
            var value = new ModCertTemplate();
            value.PkiDataReference = reader.ReadSequenceOf(Asn1Tag.Sequence, static inner => inner.ReadUInt32(Asn1Tag.Integer));
            value.CertReferences = reader.ReadSequenceOf(Asn1Tag.Sequence, static inner => inner.ReadUInt32(Asn1Tag.Integer));
            if (reader.TryPeekTag(out var tag_Replace) && tag_Replace.MatchesIgnoreConstructed(Asn1Tag.Boolean))
            {
                value.Replace = reader.ReadBoolean(Asn1Tag.Boolean);
            }
            value.CertTemplate = Asn1Kit.Modern.PKIXCRMF2009.CertTemplate.Decode(reader, Asn1Tag.Sequence);
            reader.ThrowIfNotEmpty();
            return value;
        }
    }

    public static Asn1Tag DefaultTag { get; } = Asn1Tag.Sequence;
}

